#include<bits/stdc++.h>
using namespace std;
typedef long long ll;
#define maxn 105
#define maxm 2005
const int mod = 998244353;
int s[maxn];
int a[maxn][maxm];
int dp[maxn][maxn<<1];
int ops,mats;
int prod = 1;
int main(){
	cin>>ops>>mats;
	for(int i = 1;i<=ops;i++){
		for(int j = 0;j<mats;j++){
			cin>>a[i][j];
			s[i] = (s[i]+a[i][j])%mod;
		}
		prod = 1ll*prod*(s[i]+1)%mod;
	}
	int ans = (prod+mod-1)%mod;
	for(int x = 0;x<mats;x++){
		memset(dp,0,sizeof(dp));
		dp[0][0+101] = 1;
		int no = 0;
		for(int i = 1;i<=ops;i++){
			int re = (s[i]+mod-a[i][x])%mod;
			for(int d = 1;d<=201;d++){
				dp[i][d+1] = (dp[i][d+1]+1ll*a[i][x]*dp[i-1][d])%mod;
				dp[i][d-1] = (dp[i][d-1]+1ll*re*dp[i-1][d])%mod;
				dp[i][d] = (dp[i][d]+dp[i-1][d])%mod;
			}
		}
		for(int d  =1;d<=ops;d++){
			no = (no+dp[ops][d+101])%mod;
		}
		ans = (ans+mod-no)%mod;
	}
	cout<<ans<<endl;
	return 0;
}
